import { submitJob } from '@projexlight/hdk-video-editor';
const { job_id } = await submitJob({
  tenant_id, source_blob_id, op: 'trim',
  params: { start_sec: 7200, duration_sec: 30 },
});

import { submitJob } from '@projexlight/hdk-video-editor';
const { job_id } = await submitJob({
  tenant_id, source_blob_id, op: 'redact-faces',
  params: { keep_face_persona_ids: [customer.id] },
});

import { submitJob } from '@projexlight/hdk-video-editor';
await submitJob({
  tenant_id, source_blob_id, op: 'burn-subtitles',
  params: { transcript_ref, language: 'en' },
});
